{"operations_sv":"`ifndef SPI_OPERATIONS_SVH
`define SPI_OPERATIONS_SVH
integer checks = 0;
integer total_pulses = 0;
reg spi_ops_initialized = 1'b0;
reg spi_ops_pulse_owned = 1'b0;
reg spi_ops_txn_active = 1'b0;
reg spi_ops_start_accepted = 1'b0;
integer spi_ops_low_credit = 0;

task automatic spi_ops_fail(input string name, input string msg);
$display("FAIL %s %s", name, msg);
$fatal(1, "FAIL %s %s", name, msg);
endtask

task automatic initialize_interface();
if (spi_ops_pulse_owned !== 1'b0) spi_ops_fail("initialize_interface", "pulse in progress");
if (spi_ops_initialized === 1'b1) spi_ops_fail("initialize_interface", "interface already initialized");
SCK = 1'b0;
RST_N = 1'b1;
MOSI = 1'b0;
NORM_CS_N = 1'b1;
START = 1'b0;
ENC_DEC = 1'b0;
spi_ops_txn_active = 1'b0;
spi_ops_start_accepted = 1'b0;
spi_ops_low_credit = 0;
spi_ops_initialized = 1'b1;
endtask

task automatic require_idle_clock(input string name);
if (spi_ops_initialized !== 1'b1) spi_ops_fail(name, "interface not initialized");
if (SCK !== 1'b0) spi_ops_fail(name, "SCK not known idle low");
if (spi_ops_pulse_owned !== 1'b0) spi_ops_fail(name, "concurrent pulse ownership");
endtask

task automatic sck_pulse(output reg sampled_miso, output reg sampled_busy);
require_idle_clock("sck_pulse");
if (spi_ops_low_credit < 0 || spi_ops_low_credit >= 10000) spi_ops_fail("sck_pulse", "invalid low-phase credit");
spi_ops_pulse_owned = 1'b1;
#(10000 - spi_ops_low_credit);
spi_ops_low_credit = 0;
SCK = 1'b1;
total_pulses = total_pulses + 1;
#1;
sampled_miso = MISO;
sampled_busy = BUSY;
#9999;
SCK = 1'b0;
spi_ops_pulse_owned = 1'b0;
endtask

task automatic set_mode(input reg mode);
if (mode !== 1'b0 && mode !== 1'b1) spi_ops_fail("set_mode", "unknown mode");
require_idle_clock("set_mode");
if (spi_ops_txn_active !== 1'b0) spi_ops_fail("set_mode", "transaction active");
if (BUSY !== 1'b0) spi_ops_fail("set_mode", "BUSY not known low");
ENC_DEC = mode;
endtask

task automatic apply_synchronous_reset(input string name);
reg m;
reg b;
require_idle_clock(name);
if (spi_ops_txn_active !== 1'b0) spi_ops_fail(name, "overlapping transaction");
spi_ops_txn_active = 1'b1;
spi_ops_start_accepted = 1'b0;
NORM_CS_N = 1'b1;
START = 1'b0;
RST_N = 1'b0;
sck_pulse(m, b);
if (b !== 1'b0 && b !== 1'b1) spi_ops_fail(name, "unknown BUSY on asserted reset edge");
RST_N = 1'b1;
sck_pulse(m, b);
if (b !== 1'b0 && b !== 1'b1) spi_ops_fail(name, "unknown BUSY on reset release edge");
spi_ops_txn_active = 1'b0;
check_busy(name, 1'b0);
endtask

task automatic transfer_word32(input string name, input reg [31:0] tx_word, output reg [31:0] rx_word);
integer i;
reg m;
reg b;
rx_word = 32'h00000000;
require_idle_clock(name);
if ((^tx_word) === 1'bx) spi_ops_fail(name, "unknown transmit word");
if (spi_ops_txn_active !== 1'b0) spi_ops_fail(name, "overlapping transaction");
if (START !== 1'b0) spi_ops_fail(name, "START asserted during transfer request");
if (NORM_CS_N !== 1'b1) spi_ops_fail(name, "chip-select already active");
if (BUSY !== 1'b0) spi_ops_fail(name, "core active or BUSY unknown");
spi_ops_txn_active = 1'b1;
spi_ops_start_accepted = 1'b0;
NORM_CS_N = 1'b0;
for (i = 31; i >= 0; i = i - 1) begin
MOSI = tx_word[i];
sck_pulse(m, b);
if (b !== 1'b0 && b !== 1'b1) spi_ops_fail(name, $sformatf("unknown BUSY at bit %0d", i));
if (m !== 1'b0 && m !== 1'b1) spi_ops_fail(name, $sformatf("unknown MISO at bit %0d", i));
rx_word[i] = m;
end
NORM_CS_N = 1'b1;
spi_ops_txn_active = 1'b0;
endtask

task automatic pulse_start(input string operation_name, input reg require_busy_high);
reg m;
reg b;
if (require_busy_high !== 1'b0 && require_busy_high !== 1'b1) spi_ops_fail(operation_name, "unknown require_busy_high");
require_idle_clock(operation_name);
if (spi_ops_txn_active !== 1'b0) spi_ops_fail(operation_name, "overlapping transaction");
if (NORM_CS_N !== 1'b1) spi_ops_fail(operation_name, "chip-select active during START");
if (ENC_DEC !== 1'b0 && ENC_DEC !== 1'b1) spi_ops_fail(operation_name, "unknown mode");
if (BUSY !== 1'b0) spi_ops_fail(operation_name, "core not known idle before START");
spi_ops_txn_active = 1'b1;
spi_ops_start_accepted = 1'b0;
START = 1'b1;
sck_pulse(m, b);
START = 1'b0;
$display("PROCESS %s edge=0 busy=%0b", operation_name, b);
if (b !== 1'b0 && b !== 1'b1) spi_ops_fail(operation_name, "unknown BUSY on START edge");
#1;
spi_ops_low_credit = spi_ops_low_credit + 1;
spi_ops_txn_active = 1'b0;
if (require_busy_high === 1'b1) check_busy({operation_name, ".started"}, 1'b1);
if (BUSY !== 1'b1) spi_ops_fail(operation_name, "BUSY not known high after START release");
spi_ops_start_accepted = 1'b1;
endtask

task automatic clock_until_complete(input string operation_name, input integer pulse_limit, input reg fixed_count, output integer pulses_used);
reg m;
reg b;
reg done;
integer k;
pulses_used = 0;
if ((^pulse_limit) === 1'bx) spi_ops_fail(operation_name, "unknown pulse_limit");
if (pulse_limit < 1 || pulse_limit > 64) spi_ops_fail(operation_name, "pulse_limit outside 1..64");
if (fixed_count !== 1'b0 && fixed_count !== 1'b1) spi_ops_fail(operation_name, "unknown fixed_count");
require_idle_clock(operation_name);
if (spi_ops_txn_active !== 1'b0) spi_ops_fail(operation_name, "overlapping transaction");
if (spi_ops_start_accepted !== 1'b1) spi_ops_fail(operation_name, "no accepted START");
if (BUSY !== 1'b1) spi_ops_fail(operation_name, "idle before start");
spi_ops_txn_active = 1'b1;
done = 1'b0;
for (k = 1; k <= pulse_limit; k = k + 1) begin
if (fixed_count === 1'b0 && done === 1'b1) break;
sck_pulse(m, b);
pulses_used = pulses_used + 1;
$display("PROCESS %s edge=%0d busy=%0b", operation_name, pulses_used, b);
if (b !== 1'b0 && b !== 1'b1) spi_ops_fail(operation_name, $sformatf("unknown BUSY at edge %0d", k));
if (k == 1 && b !== 1'b1) spi_ops_fail(operation_name, "BUSY low on first post-START edge");
if (done === 1'b1 && b === 1'b1) spi_ops_fail(operation_name, $sformatf("BUSY reasserted at edge %0d", k));
if (b === 1'b0) done = 1'b1;
end
spi_ops_txn_active = 1'b0;
spi_ops_start_accepted = 1'b0;
if (done !== 1'b1) spi_ops_fail(operation_name, "timeout waiting for BUSY low");
check_busy({operation_name, ".complete"}, 1'b0);
endtask

task automatic read_result(input string name, input reg [31:0] mosi_word, output reg [31:0] result);
transfer_word32(name, mosi_word, result);
endtask

task automatic check_busy(input string name, input reg expected);
reg observed;
observed = BUSY;
if (expected !== 1'b0 && expected !== 1'b1) spi_ops_fail(name, "unknown expected BUSY");
if (observed !== 1'b0 && observed !== 1'b1) spi_ops_fail(name, "unknown observed BUSY");
if (observed !== expected) spi_ops_fail(name, $sformatf("busy=%0b expected=%0b", observed, expected));
checks = checks + 1;
$display("PASS %s busy=%0b", name, observed);
endtask

task automatic check_word32(input string name, input reg [31:0] actual, input reg [31:0] expected);
if ((^expected) === 1'bx) spi_ops_fail(name, "unknown expected word");
if ((^actual) === 1'bx) spi_ops_fail(name, $sformatf("unknown actual word %h", actual));
if (actual !== expected) spi_ops_fail(name, $sformatf("value=%08h expected=%08h", actual, expected));
checks = checks + 1;
$display("PASS %s value=%08h", name, actual);
endtask
`endif
","testbench_sv":"`timescale 1ns/1ps
module crypto_tb;
reg SCK;
reg RST_N;
reg MOSI;
reg NORM_CS_N;
reg START;
reg ENC_DEC;
wire MISO;
wire BUSY;
wire ICE_LED;
`include "spi_operations.svh"

reg [3:0] STEP;
reg [1:0] RANDOM_PHASE;
reg [31:0] RANDOM_WORD;
wire c_valid;
wire [2:0] c_action;
wire c_mode;
wire c_set_mode;
wire [31:0] c_tx_word;
wire [31:0] c_expected_word;
wire c_check_word;
wire c_require_busy;
wire [6:0] c_pulse_limit;
wire c_fixed_count;

reg [2:0] l_action;
reg l_mode;
reg l_set_mode;
reg [31:0] l_tx_word;
reg [31:0] l_expected_word;
reg l_check_word;
reg l_require_busy;
reg [6:0] l_pulse_limit;
reg l_fixed_count;

reg [2:0] e_action;
reg e_mode;
reg e_set_mode;
reg [31:0] e_tx_word;
reg [31:0] e_expected_word;
reg e_check_word;
reg e_require_busy;
reg [6:0] e_pulse_limit;
reg e_fixed_count;

string tb_reset_name;
string tb_xfer_name;
string tb_check_name;
string tb_op_name;
string tb_arg_text;
reg [63:0] tb_parsed;
reg [31:0] tb_seed;
integer tb_random_trials;
reg [31:0] tb_lcg_state;
reg [31:0] tb_rx;
integer tb_used;
integer tb_step;
integer tb_phase;
integer tb_trial;
integer baseline_pulses;

localparam [31:0] TB_P = 32'h59c359c3;
localparam [31:0] TB_C = 32'h9cd84392;

crypto_dut dut (
.SCK(SCK),
.RST_N(RST_N),
.MOSI(MOSI),
.NORM_CS_N(NORM_CS_N),
.START(START),
.ENC_DEC(ENC_DEC),
.MISO(MISO),
.BUSY(BUSY),
.ICE_LED(ICE_LED)
);

spi_testbench_controller controller (
.STEP(STEP),
.RANDOM_PHASE(RANDOM_PHASE),
.RANDOM_WORD(RANDOM_WORD),
.VALID(c_valid),
.ACTION(c_action),
.MODE(c_mode),
.SET_MODE(c_set_mode),
.TX_WORD(c_tx_word),
.EXPECTED_WORD(c_expected_word),
.CHECK_WORD(c_check_word),
.REQUIRE_BUSY(c_require_busy),
.PULSE_LIMIT(c_pulse_limit),
.FIXED_COUNT(c_fixed_count)
);

task automatic tb_parse_decimal(input string name, input string text, input reg [63:0] limit, output reg [63:0] value);
integer i;
reg [7:0] ch;
reg [63:0] d;
value = 64'd0;
if (text.len() == 0) spi_ops_fail(name, "empty value");
for (i = 0; i < text.len(); i = i + 1) begin
ch = text[i];
if (ch < 8'd48 || ch > 8'd57) spi_ops_fail(name, $sformatf("malformed value %s", text));
d = {56'd0, ch - 8'd48};
if (value > (limit - d) / 64'd10) spi_ops_fail(name, $sformatf("value out of range %s", text));
value = value * 64'd10 + d;
end
endtask

task automatic tb_latch_command(input string ctx);
require_idle_clock(ctx);
#1;
spi_ops_low_credit = spi_ops_low_credit + 1;
if (c_valid !== 1'b1) spi_ops_fail(ctx, "controller VALID not high");
if ((^{c_action, c_mode, c_set_mode, c_tx_word, c_expected_word, c_check_word, c_require_busy, c_pulse_limit, c_fixed_count}) === 1'bx) spi_ops_fail(ctx, "controller output unknown");
l_action = c_action;
l_mode = c_mode;
l_set_mode = c_set_mode;
l_tx_word = c_tx_word;
l_expected_word = c_expected_word;
l_check_word = c_check_word;
l_require_busy = c_require_busy;
l_pulse_limit = c_pulse_limit;
l_fixed_count = c_fixed_count;
endtask

task automatic tb_verify_command(input string ctx);
if (l_action !== e_action) spi_ops_fail(ctx, $sformatf("ACTION %0d expected %0d", l_action, e_action));
if (l_mode !== e_mode) spi_ops_fail(ctx, "MODE mismatch");
if (l_set_mode !== e_set_mode) spi_ops_fail(ctx, "SET_MODE mismatch");
if (l_tx_word !== e_tx_word) spi_ops_fail(ctx, $sformatf("TX_WORD %08h expected %08h", l_tx_word, e_tx_word));
if (l_expected_word !== e_expected_word) spi_ops_fail(ctx, $sformatf("EXPECTED_WORD %08h expected %08h", l_expected_word, e_expected_word));
if (l_check_word !== e_check_word) spi_ops_fail(ctx, "CHECK_WORD mismatch");
if (l_require_busy !== e_require_busy) spi_ops_fail(ctx, "REQUIRE_BUSY mismatch");
if (l_pulse_limit !== e_pulse_limit) spi_ops_fail(ctx, "PULSE_LIMIT mismatch");
if (l_fixed_count !== e_fixed_count) spi_ops_fail(ctx, "FIXED_COUNT mismatch");
endtask

task automatic tb_clear_expected();
e_action = 3'd0;
e_mode = 1'b0;
e_set_mode = 1'b0;
e_tx_word = 32'd0;
e_expected_word = 32'd0;
e_check_word = 1'b0;
e_require_busy = 1'b0;
e_pulse_limit = 7'd0;
e_fixed_count = 1'b0;
tb_reset_name = "";
tb_xfer_name = "";
tb_check_name = "";
tb_op_name = "";
endtask

task automatic tb_baseline_expected(input integer step);
tb_clear_expected();
if (step >= 6) e_mode = 1'b1;
case (step)
0: begin e_action = 3'd1; tb_reset_name = "baseline.reset"; end
1: begin e_action = 3'd2; e_tx_word = TB_P; tb_xfer_name = "baseline.load_plaintext"; end
2: begin e_action = 3'd2; e_tx_word = TB_P; e_expected_word = TB_P; e_check_word = 1'b1; tb_xfer_name = "baseline.echo_read"; tb_check_name = "baseline.echo"; end
3: begin e_action = 3'd3; e_set_mode = 1'b1; e_require_busy = 1'b1; tb_op_name = "encrypt"; end
4: begin e_action = 3'd4; e_pulse_limit = 7'd7; e_fixed_count = 1'b1; tb_op_name = "encrypt"; end
5: begin e_action = 3'd2; e_tx_word = TB_P; e_expected_word = TB_C; e_check_word = 1'b1; tb_xfer_name = "baseline.encrypt_read"; tb_check_name = "baseline.encrypt"; end
6: begin e_action = 3'd1; e_set_mode = 1'b1; tb_reset_name = "baseline.decrypt_reset"; end
7: begin e_action = 3'd2; e_tx_word = TB_C; tb_xfer_name = "baseline.load_ciphertext"; end
8: begin e_action = 3'd3; tb_op_name = "decrypt"; end
9: begin e_action = 3'd4; e_pulse_limit = 7'd7; e_fixed_count = 1'b1; tb_op_name = "decrypt"; end
10: begin e_action = 3'd2; e_tx_word = TB_C; e_expected_word = TB_P; e_check_word = 1'b1; tb_xfer_name = "baseline.decrypt_read"; tb_check_name = "baseline.decrypt"; end
11: e_action = 3'd5;
default: spi_ops_fail("baseline", "invalid step");
endcase
endtask

task automatic tb_dispatch(input string ctx);
