2: begin e_action = 3'd2; e_tx_word = tb_lcg_state; tb_xfer_name = $sformatf("random_echo.%0d.load", tb_trial); end
default: begin e_action = 3'd2; e_tx_word = tb_lcg_state; e_expected_word = tb_lcg_state; e_check_word = 1'b1; tb_xfer_name = $sformatf("random_echo.%0d.read", tb_trial); tb_check_name = $sformatf("random_echo.%0d", tb_trial); end
endcase
